// Enumerate every order of two read/write steps from A and two from B while preserving each participant’s read-before-write order. Count final values in this sequential model.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>

int main() {
    int counter = 0;
    const int a_read = counter;
    const int b_read = counter;
    counter = a_read + 1;
    counter = b_read + 1;
    std::cout << counter << '\n';
    assert(counter == 1);
}

#include <array>
#include <cassert>
#include <iostream>
#include <map>
#include <algorithm>

std::map<int,unsigned> outcomes() {
    std::array<int,4> order{0,0,1,1};
    std::map<int,unsigned> counts;
    do {
        int counter = 0;
        std::array<int,2> local{0,0}, step{0,0};
        for(int who : order) {
            if(step[who]++ == 0) local[who] = counter;
            else counter = local[who]+1;
        }
        ++counts[counter];
    } while(std::next_permutation(order.begin(),order.end()));
    return counts;
}

int main() {
    const auto counts = outcomes();
    assert(counts.at(1) == 4 && counts.at(2) == 2);
    std::cout << "lost=" << counts.at(1) << " serialized=" << counts.at(2) << '\n';
}

